//! Literal numbers and number words allowed in templates and ledger rows. Each entry: the
//! file, an anchor that must match exactly one line, the whole token, and its source, which
//! must quote the token.

/// One allowed literal.
pub struct Entry {
    pub file: &'static str,
    pub anchor: &'static str,
    pub token: &'static str,
    pub source: &'static str,
}

const fn e(
    file: &'static str,
    anchor: &'static str,
    token: &'static str,
    source: &'static str,
) -> Entry {
    Entry {
        file,
        anchor,
        token,
        source,
    }
}

